import{_ as i,o as n,c as a,ai as p}from"./chunks/framework.BxxKhjs3.js";const l="/pub-blog/assets/image-20250912220119958.BLAcxnpO.png",e="/pub-blog/assets/image-20250912223003666.CuQ1Qd1s.png",h="/pub-blog/assets/image-20250822223258675.CJHnmYEl.png",t="/pub-blog/assets/wanshaoweixin.DWzIcicW.jpg",b=JSON.parse("{\"title\":\"可可图片编辑 HarmonyOS（6）水印效果\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（6）水印效果/可可图片编辑 HarmonyOS（6）水印效果.md\",\"filePath\":\"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（6）水印效果/可可图片编辑 HarmonyOS（6）水印效果.md\",\"lastUpdated\":1757689175000,\"__rawMarkdown\":\"# 可可图片编辑 HarmonyOS（6）水印效果\\n\\n## 前言\\n\\n可可图片编辑  也实现了水印效果，这个功能的实现比较取巧。\\n\\n在预览阶段，直接通过层叠布局来实现水印效果。\\n\\n在保存图片时，使用组件截图  **componentSnapshot** 的知识实现保存图片。\\n\\n> https://developer.huawei.com/consumer/cn/doc/harmonyos-references/js-apis-arkui-componentsnapshot#componentsnapshotgetdeprecated\\n\\n![image-20250912220119958](assets/image-20250912220119958.png)\\n\\n\\n\\n\\n\\n## `componentSnapshot` 介绍 \\n\\n`componentSnapshot` 是 HarmonyOS提供的一个强大功能，允许开发者获取应用中组件的截图，生成 PixelMap 格式的图片数据。这对于实现**分享功能**、**内容保存**、**动态生成图片**等场景非常有用。\\n\\n\\n\\n## 基本使用步骤\\n\\n### 1. 准备工作：添加组件标识\\n\\n首先需要为想要截图的组件添加唯一标识：\\n\\n```typescript\\n// 在build方法中为组件添加id\\nbuild() {\\n  Column() {\\n    // 需要截图的组件\\n    Column() {\\n      Text('这是要截图的内容')\\n        .fontSize(20)\\n      Image($r('app.media.icon'))\\n        .width(100)\\n        .height(100)\\n    }\\n    .id('targetComponent') // 添加唯一标识\\n    \\n    // 其他UI组件...\\n  }\\n}\\n```\\n\\n### 2. 获取截图的基本方法\\n\\n#### 方法一：异步获取（推荐）\\n\\n```typescript\\nimport { image } from '@kit.ImageKit';\\n\\n// 在按钮点击或其他事件中\\nasync takeScreenshot() {\\n  try {\\n    // 获取UIContext\\n    const uiContext = this.getUIContext();\\n    \\n    // 使用componentSnapshot获取截图\\n    const pixelMap = await uiContext.getComponentSnapshot()\\n      .get('targetComponent', { \\n        scale: 1.0, // 缩放比例\\n        waitUntilRenderFinished: true // 等待渲染完成\\n      });\\n    \\n    // 处理截图结果\\n    this.handleScreenshotResult(pixelMap);\\n  } catch (error) {\\n    console.error('截图失败:', error);\\n  }\\n}\\n\\n// 处理截图结果\\nhandleScreenshotResult(pixelMap: image.PixelMap) {\\n  // 可以显示在Image组件中\\n  this.screenshotImage = pixelMap;\\n  \\n  // 或者保存到文件\\n  // this.saveToFile(pixelMap);\\n}\\n```\\n\\n#### 方法二：同步获取\\n\\n```typescript\\ntakeScreenshotSync() {\\n  try {\\n    const uiContext = this.getUIContext();\\n    const pixelMap = uiContext.getComponentSnapshot()\\n      .getSync('targetComponent', {\\n        scale: 0.8,\\n        waitUntilRenderFinished: true\\n      });\\n    \\n    this.handleScreenshotResult(pixelMap);\\n  } catch (error) {\\n    console.error('同步截图失败:', error);\\n  }\\n}\\n```\\n\\n### 3. 显示截图结果\\n\\n```typescript\\n// 在build方法中显示截图\\nbuild() {\\n  Column() {\\n    // 原始内容\\n    Column() {\\n      // ...原有内容\\n    }\\n    .id('targetComponent')\\n    \\n    // 截图结果显示\\n    Image(this.screenshotImage)\\n      .width(200)\\n      .height(200)\\n      .margin(10)\\n      .visibility(this.screenshotImage ? Visibility.Visible : Visibility.None)\\n    \\n    // 截图按钮\\n    Button('截图')\\n      .onClick(() => this.takeScreenshot())\\n      .margin(10)\\n  }\\n}\\n```\\n\\n![image-20250912223003666](assets/image-20250912223003666.png)\\n\\n### 4. 完整示例代码\\n\\n```typescript\\nimport { image } from '@kit.ImageKit';\\n\\n@Entry\\n@Component\\nstruct ScreenshotExample {\\n  @State screenshotImage: image.PixelMap | undefined = undefined;\\n\\n  // 异步截图方法\\n  async takeScreenshot() {\\n    try {\\n      const uiContext = this.getUIContext();\\n      const pixelMap = await uiContext.getComponentSnapshot()\\n        .get('contentToCapture', {\\n          scale: 1.0,\\n          waitUntilRenderFinished: true\\n        });\\n      \\n      this.screenshotImage = pixelMap;\\n    } catch (error) {\\n      console.error('截图失败:', error);\\n    }\\n  }\\n\\n  build() {\\n    Column({ space: 20 }) {\\n      // 目标截图区域\\n      Column() {\\n        Text('欢迎使用组件截图功能')\\n          .fontSize(24)\\n          .fontColor(Color.Blue)\\n        \\n        Text('这是可以截图的内容区域')\\n          .fontSize(16)\\n          .margin({ top: 10 })\\n        \\n        Image($r('app.media.logo'))\\n          .width(120)\\n          .height(120)\\n          .margin({ top: 20 })\\n      }\\n      .id('contentToCapture')\\n      .padding(20)\\n      .border({ width: 2, color: Color.Gray })\\n\\n      // 截图结果显示\\n      if (this.screenshotImage) {\\n        Image(this.screenshotImage)\\n          .width(300)\\n          .height(200)\\n          .border({ width: 1, color: Color.Black })\\n      }\\n\\n      // 操作按钮\\n      Button('截图')\\n        .width(120)\\n        .onClick(() => this.takeScreenshot())\\n    }\\n    .width('100%')\\n    .padding(20)\\n  }\\n}\\n```\\n\\n### 5.  SnapshotOptions  重要参数说明\\n\\n### 配置选项：\\n\\n- **scale**: number - 缩放比例（0.1-1.0），默认1.0\\n- waitUntilRenderFinished: boolean - 是否等待渲染完成（推荐设为true）\\n- region: Object - 指定截图区域\\n  - start: number - 起始x坐标\\n  - top: number - 起始y坐标\\n  - end: number - 结束x坐标\\n  - bottom: number - 结束y坐标\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n## 以往文章\\n\\n- 我的iMaHarmonyOS 知识库接入 鸿蒙6 API20 新特性了 \\n\\n  > https://mp.weixin.qq.com/s/YsbFQyi5PsndpRUaA9h_dA?token=830743671&lang=zh_CN\\n\\n- 鸿蒙创新赛 HarmonyOS 6.0.0(20) 关键特性汇总\\n\\n  > https://mp.weixin.qq.com/s/ERmgSAIT8B8njFqtyPx9IQ\\n\\n- 可可图片编辑 HarmonyOS（4）图片裁剪-canvas\\n\\n  > https://mp.weixin.qq.com/s/2M3f_LNnt0YRo0qEnCnqpA\\n\\n- 可可图片编辑 HarmonyOS（3）应用间分享图片\\n\\n  > https://mp.weixin.qq.com/s/n8kkdougB4lqDHjYC7co8g\\n\\n\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n> https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248\\n\\n![](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![](assets/wanshaoweixin.jpg)\"}"),k={name:"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（6）水印效果/可可图片编辑 HarmonyOS（6）水印效果.md"};function r(E,s,d,c,g,o){return n(),a("div",null,[...s[0]||(s[0]=[p("",35)])])}const m=i(k,[["render",r]]);export{b as __pageData,m as default};
